<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Personal Expense Tracker</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; background: #f4f6f8; color: #222; padding: 24px; max-width: 860px; margin: 0 auto; }
  h1 { font-size: 1.6rem; margin-bottom: 20px; text-align: center; }
  h2 { font-size: 1.15rem; margin: 24px 0 10px; border-bottom: 1px solid #ccc; padding-bottom: 4px; }

  /* Form */
  .form-row { display: flex; flex-wrap: wrap; gap: 8px; align-items: flex-end; margin-bottom: 8px; }
  .form-group { display: flex; flex-direction: column; gap: 2px; }
  .form-group label { font-size: 0.8rem; font-weight: 600; color: #555; }
  input, select { padding: 7px 10px; border: 1px solid #bbb; border-radius: 4px; font-size: 0.95rem; background: #fff; }
  input:focus, select:focus { outline: 2px solid #3b82f6; border-color: #3b82f6; }
  #add-expense { padding: 7px 18px; background: #3b82f6; color: #fff; border: none; border-radius: 4px; font-size: 0.95rem; cursor: pointer; white-space: nowrap; align-self: flex-end; }
  #add-expense:hover { background: #2563eb; }
  #form-error { color: #b91c1c; font-weight: 600; min-height: 1.4em; padding: 4px 0; }

  /* Filters */
  .filters-row { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin-bottom: 12px; padding: 10px 12px; background: #e9ecef; border-radius: 6px; }
  .filters-row label { font-size: 0.8rem; font-weight: 600; color: #555; }
  .filter-group { display: flex; align-items: center; gap: 4px; }

  /* Expense list */
  #expense-list { list-style: none; }
  .expense { display: flex; justify-content: space-between; align-items: center; background: #fff; padding: 10px 14px; margin-bottom: 6px; border-radius: 5px; border: 1px solid #ddd; transition: opacity 0.2s; }
  .expense.hidden { display: none; }
  .expense-info { display: flex; gap: 18px; align-items: center; flex-wrap: wrap; }
  .expense-amount { font-weight: 700; font-size: 1rem; min-width: 70px; text-align: right; }
  .expense-cat { background: #e0e7ff; color: #3730a3; padding: 2px 8px; border-radius: 4px; font-size: 0.82rem; font-weight: 600; text-transform: capitalize; }
  .expense-date { font-size: 0.85rem; color: #777; }
  .exp-del { background: #ef4444; color: #fff; border: none; border-radius: 4px; padding: 5px 12px; cursor: pointer; font-size: 0.85rem; }
  .exp-del:hover { background: #b91c1c; }

  /* Summary */
  #total-display { font-size: 1.3rem; font-weight: 700; padding: 10px 0; margin-top: 6px; border-top: 2px solid #333; }
  .cat-total-row { display: flex; justify-content: space-between; padding: 5px 0; border-bottom: 1px dotted #ccc; font-size: 0.95rem; }
  .cat-total-row span:last-child { font-weight: 600; }
</style>
</head>
<body>

<h1>Expense Tracker</h1>

<!-- Entry Form -->
<form id="expense-form">
  <div class="form-row">
    <div class="form-group">
      <label for="amount">Amount ($)</label>
      <input type="number" id="amount" min="0.01" step="0.01" placeholder="0.00">
    </div>
    <div class="form-group">
      <label for="category">Category</label>
      <select id="category">
        <option value="groceries">Groceries</option>
        <option value="transport">Transport</option>
        <option value="bills">Bills</option>
        <option value="fun">Fun</option>
      </select>
    </div>
    <div class="form-group">
      <label for="date">Date</label>
      <input type="date" id="date">
    </div>
    <div class="form-group">
      <label for="note">Note (optional)</label>
      <input type="text" id="note" placeholder="e.g. Weekly shopping">
    </div>
  </div>
  <div class="form-row">
    <button type="submit" id="add-expense">Add Expense</button>
  </div>
  <div id="form-error"></div>
</form>

<!-- Filters -->
<h2>Filters</h2>
<div class="filters-row">
  <div class="filter-group">
    <label for="filter-category">Category:</label>
    <select id="filter-category">
      <option value="all">All</option>
      <option value="groceries">Groceries</option>
      <option value="transport">Transport</option>
      <option value="bills">Bills</option>
      <option value="fun">Fun</option>
    </select>
  </div>
  <div class="filter-group">
    <label for="filter-from">From:</label>
    <input type="date" id="filter-from">
  </div>
  <div class="filter-group">
    <label for="filter-to">To:</label>
    <input type="date" id="filter-to">
  </div>
</div>

<!-- List -->
<h2>Expenses</h2>
<ul id="expense-list"></ul>

<!-- Summary -->
<h2>Summary</h2>
<div id="total-display">Total: $0.00</div>
<div id="category-summary"></div>

<script>
(function() {
  "use strict";

  // --- State ---
  const STORAGE_KEY = "expense-tracker-data";
  let expenses = loadExpenses();

  function loadExpenses() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      return raw ? JSON.parse(raw) : [];
    } catch(e) {
      return [];
    }
  }

  function saveExpenses() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
  }

  // --- DOM refs ---
  const form = document.getElementById("expense-form");
  const amountInput = document.getElementById("amount");
  const categorySelect = document.getElementById("category");
  const dateInput = document.getElementById("date");
  const noteInput = document.getElementById("note");
  const addBtn = document.getElementById("add-expense");
  const formError = document.getElementById("form-error");

  const filterCategory = document.getElementById("filter-category");
  const filterFrom = document.getElementById("filter-from");
  const filterTo = document.getElementById("filter-to");

  const expenseListEl = document.getElementById("expense-list");
  const totalDisplay = document.getElementById("total-display");
  const categorySummaryEl = document.getElementById("category-summary");

  // --- Defaults ---
  dateInput.valueAsDate = new Date();

  // --- Validation ---
  function validate() {
    formError.textContent = "";
    const val = amountInput.value.trim();
    if (val === "") {
      formError.textContent = "Amount is required.";
      return false;
    }
    const num = Number(val);
    if (isNaN(num)) {
      formError.textContent = "Amount must be a valid number.";
      return false;
    }
    if (num <= 0) {
      formError.textContent = "Amount must be greater than zero.";
      return false;
    }
    if (!dateInput.value) {
      formError.textContent = "Date is required.";
      return false;
    }
    return true;
  }

  // --- Add Expense ---
  form.addEventListener("submit", function(e) {
    e.preventDefault();
    if (!validate()) return;

    const expense = {
      id: Date.now() + Math.random(),
      amount: parseFloat(amountInput.value),
      category: categorySelect.value,
      date: dateInput.value,
      note: noteInput.value.trim()
    };

    expenses.push(expense);
    saveExpenses();
    render();

    // Clear amount and reset form partially
    amountInput.value = "";
    noteInput.value = "";
    formError.textContent = "";
  });

  // --- Delete Expense ---
  expenseListEl.addEventListener("click", function(e) {
    if (e.target.classList.contains("exp-del")) {
      const idStr = e.target.getAttribute("data-id");
      expenses = expenses.filter(function(exp) { return String(exp.id) !== idStr; });
      saveExpenses();
      render();
    }
  });

  // --- Filter Change ---
  filterCategory.addEventListener("change", render);
  filterFrom.addEventListener("change", render);
  filterTo.addEventListener("change", render);

  // --- Rendering ---
  function getFilteredExpenses() {
    const catFilter = filterCategory.value;
    const fromVal = filterFrom.value;
    const toVal = filterTo.value;

    return expenses.filter(function(exp) {
      if (catFilter !== "all" && exp.category !== catFilter) return false;
      if (fromVal && exp.date < fromVal) return false;
      if (toVal && exp.date > toVal) return false;
      return true;
    });
  }

  function formatCurrency(n) {
    return n.toFixed(2);
  }

  function render() {
    const filtered = getFilteredExpenses();

    // Sort newest first
    filtered.sort(function(a, b) {
      if (b.date !== a.date) return b.date.localeCompare(a.date);
      return b.id - a.id;
    });

    // Build list
    expenseListEl.innerHTML = "";
    filtered.forEach(function(exp) {
      const li = document.createElement("li");
      li.className = "expense";
      li.setAttribute("data-id", String(exp.id));

      const info = document.createElement("span");
      info.className = "expense-info";

      const amtEl = document.createElement("span");
      amtEl.className = "expense-amount";
      amtEl.textContent = "$" + formatCurrency(exp.amount);

      const catEl = document.createElement("span");
      catEl.className = "expense-cat";
      catEl.textContent = exp.category;

      const dateEl = document.createElement("span");
      dateEl.className = "expense-date";
      dateEl.textContent = exp.date;

      info.appendChild(amtEl);
      info.appendChild(catEl);
      info.appendChild(dateEl);
      if (exp.note) {
        const noteEl = document.createElement("span");
        noteEl.style.fontStyle = "italic";
        noteEl.style.color = "#666";
        noteEl.style.fontSize = "0.85rem";
        noteEl.textContent = exp.note;
        info.appendChild(noteEl);
      }

      const delBtn = document.createElement("button");
      delBtn.className = "exp-del";
      delBtn.textContent = "Delete";
      delBtn.setAttribute("data-id", String(exp.id));

      li.appendChild(info);
      li.appendChild(delBtn);
      expenseListEl.appendChild(li);
    });

    // Total
    const total = filtered.reduce(function(sum, exp) { return sum + exp.amount; }, 0);
    totalDisplay.textContent = "Total: $" + formatCurrency(total);

    // Category summary
    categorySummaryEl.innerHTML = "";
    const cats = ["groceries", "transport", "bills", "fun"];
    cats.forEach(function(cat) {
      const catFiltered = filtered.filter(function(e) { return e.category === cat; });
      const catTotal = catFiltered.reduce(function(s, e) { return s + e.amount; }, 0);

      const row = document.createElement("div");
      row.className = "cat-total-row";
      row.setAttribute("data-cat", cat);
      row.innerHTML = '<span style="text-transform:capitalize">' + cat + '</span><span>$' + formatCurrency(catTotal) + '</span>';
      categorySummaryEl.appendChild(row);
    });
  }

  // Initial render
  render();
})();
</script>

</body>
</html>
